#include <filesystem>
#include <fstream>
#include <string>
#include <cassert>
#include <type_traits>
#include <utility>
#include <chrono>
struct Directory {
    std::filesystem::path path = std::filesystem::temp_directory_path() /
        ("cpp-library-dir-" +
            std::to_string(
                std::chrono::steady_clock::now().time_since_epoch().count()));
    Directory() { std::filesystem::create_directory(path); }
    ~Directory() {
        std::error_code error;
        std::filesystem::remove_all(path, error);
    }
} directory;
std::error_code error;
int main() {
    namespace fs = std::filesystem;
    fs::path path = directory.path / "file";
    auto copy = path;
    copy.assign(path);
    assert(copy == path && copy.has_filename() && !copy.empty());
    assert(path.is_absolute() && !path.is_relative());
    copy.clear();
    assert(copy.empty());
    copy = path;
    copy.swap(path);
    std::swap(copy, path);
    auto format = fs::path::generic_format;
    (void)format;
    {
        std::ofstream output{path};
        output << "data";
    }
    fs::directory_entry entry{path}, other;
    other = entry;
    assert(other == entry);
    entry.refresh();
    assert(entry.hard_link_count() >= 1);
    fs::file_status status{fs::file_type::regular};
    fs::file_status assigned;
    assigned = status;
    assigned.type(fs::file_type::directory);
    assert(status.type() == fs::file_type::regular && status.type() != assigned.type());
    assert(fs::status_known(status) && !fs::is_other(status));
    fs::directory_iterator begin{directory.path}, end;
    assert(begin != end && begin->path() == path);
    auto cursor = begin;
    cursor.increment(error);
    assert(!error && cursor == end);
    fs::create_directory(directory.path / "nested");
    {
        std::ofstream nestedFile{directory.path / "nested" / "child"};
        nestedFile << "child";
    }
    fs::recursive_directory_iterator recursive{
        directory.path, fs::directory_options::none};
    assert(recursive.options() == fs::directory_options::none);
    assert(recursive.recursion_pending());
    auto moved = recursive;
    recursive = moved;
    (void)*recursive;
    recursive.increment(error);
    assert(!error);
    auto nestedCursor = fs::recursive_directory_iterator(directory.path);
    while (
        nestedCursor != fs::recursive_directory_iterator{} && nestedCursor.depth() == 0)
        ++nestedCursor;
    assert(nestedCursor.depth() == 1);
    nestedCursor.pop();
    fs::filesystem_error failure{
        "test", path, std::make_error_code(std::errc::invalid_argument)},
        assignedError = failure;
    assignedError = failure;
    assert(assignedError.path1() == path);
    fs::create_symlink(path, directory.path / "link", error);
    if (!error) {
        fs::copy_symlink(directory.path / "link", directory.path / "copy", error);
        assert(!error && fs::is_symlink(directory.path / "copy"));
    }
}
